export interface FocusTrapOptions {
  container: HTMLElement;
  exclude?: string;
  onFocus?: (element: HTMLElement) => void;
  onBlur?: (element: HTMLElement) => void;
}

export class FocusTrap {
  private readonly options: FocusTrapOptions;
  private active = false;
  private previouslyFocusedElement: HTMLElement | null = null;
  private container: HTMLElement;
  private excludeElements: Set<HTMLElement> = new Set();
  private onFocusCallback: ((element: HTMLElement) => void) | undefined;
  private onBlurCallback: ((element: HTMLElement) => void) | undefined;

  constructor(options: FocusTrapOptions) {
    this.container = options.container;
    this.excludeElements = new Set();
    this.onFocusCallback = options.onFocus ?? ((el) => {});
    this.onBlurCallback = options.onBlur ?? ((el) => {});

    if (options.exclude) {
      const el = document.querySelector(options.exclude);
      if (el) this.excludeElements.add(el);
    }
  }

  activate(): void {
    if (this.active) return;
    this.active = true;
    this.previouslyFocusedElement = document.activeElement as HTMLElement;

    const currentFocus = document.activeElement as HTMLElement | null;

    this.container.addEventListener("mousedown", this.handleMouseDown);
    this.container.addEventListener("keydown", this.handleKeyDown);
    this.container.addEventListener("focusin", this.handleFocusIn);

    const firstFocusable = this.getFirstFocusableElement();
    if (firstFocusable) {
      firstFocusable.focus();
    } else if (this.container === document.activeElement) {
      this.container.setAttribute("tabindex", "-1");
    }
  }

  deactivate(): void {
    if (!this.active) return;
    this.active = false;

    this.container.removeEventListener("mousedown", this.handleMouseDown);
    this.container.removeEventListener("keydown", this.handleKeyDown);
    this.container.removeEventListener("focusin", this.handleFocusIn);

    if (this.previouslyFocusedElement) {
      try {
        this.previouslyFocusedElement.focus();
      } catch {
      }
    } else {
      this.container.focus();
    }
  }

  private handleMouseDown = (e: MouseEvent): void => {
    if (!this.container.contains(e.target as Node)) {
      e.preventDefault();
      this.container.focus();
    }
  };

  private handleKeyDown = (e: KeyboardEvent): void => {
    const tabKey = e.key === "Tab" || e.key === "Shift+Tab";
    if (!tabKey) return;

    if (!this.container.contains(document.activeElement as Node)) return;

    const focusable = this.getFocusableElements();
    if (focusable.length === 0) {
      e.preventDefault();
      return;
    }

    const [firstEl, lastEl] = this.getFirstAndLast(focusable);

    if (e.shiftKey && document.activeElement === firstEl) {
      e.preventDefault();
      lastEl.focus();
    } else if (!e.shiftKey && document.activeElement === lastEl) {
      e.preventDefault();
      firstEl.focus();
    }
  };

  private handleFocusIn = (e: FocusEvent): void => {
    const target = e.target as HTMLElement;
    this.onFocusCallback(target);
  };

  private getFocusableElements(): HTMLElement[] {
    return Array.from(this.container.querySelectorAll<HTMLElement>("[tabindex]:not([tabindex='-1'])")).filter(
      (el) => !this.excludeElements.has(el)
    );
  }

  private getFirstAndLast(focusable: HTMLElement[]): [HTMLElement, HTMLElement] {
    if (focusable.length === 0) return [this.container as HTMLElement, this.container as HTMLElement];
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    return [first, last];
  }

  private getFirstFocusableElement(): HTMLElement | null {
    const focusable = this.getFocusableElements();
    return focusable.length > 0 ? focusable[0] : null;
  }
}
